import asyncio
import weakref
import uuid
from dataclasses import dataclass, field
from typing import Dict, Optional, Callable, Any
from collections import defaultdict


@dataclass
class TenantContext:
    tenant_id: str
    api_key: str
    rate_limit: int = 100
    sent_count: int = 0
    _callbacks: list = field(default_factory=list)
    _invalidated: bool = False

    def register_callback(self, cb: Callable):
        self._callbacks.append(cb)

    def fire_callbacks(self, event: dict):
        if self._invalidated:
            return
        for cb in self._callbacks:
            cb(event)

    def invalidate(self):
        self._invalidated = True
        self._callbacks.clear()


class TenantRegistry:
    def __init__(self):
        self._tenants: Dict[str, TenantContext] = {}
        self._pending_deliveries: Dict[str, dict] = {}

    def register(self, tenant_id: str, api_key: str) -> TenantContext:
        ctx = TenantContext(tenant_id=tenant_id, api_key=api_key)
        self._tenants[tenant_id] = ctx
        return ctx

    def unregister(self, tenant_id: str):
        if tenant_id in self._tenants:
            ctx = self._tenants[tenant_id]
            ctx.invalidate()
            del self._tenants[tenant_id]

    def get(self, tenant_id: str) -> Optional[TenantContext]:
        return self._tenants.get(tenant_id)

    def store_pending(self, delivery_id: str, metadata: dict):
        self._pending_deliveries[delivery_id] = metadata

    def get_pending(self, delivery_id: str) -> Optional[dict]:
        return self._pending_deliveries.get(delivery_id)

    def remove_pending(self, delivery_id: str):
        self._pending_deliveries.pop(delivery_id, None)


class EmailDeliveryEngine:
    def __init__(self, registry: TenantRegistry):
        self._registry = registry
        self._delivery_tenant_ids: Dict[str, str] = {}

    async def send_email(self, tenant_id: str, recipient: str, subject: str, body: str) -> str:
        ctx = self._registry.get(tenant_id)
        if ctx is None:
            raise ValueError(f"Unknown tenant: {tenant_id}")

        if ctx.sent_count >= ctx.rate_limit:
            raise RuntimeError(f"Rate limit exceeded for tenant {tenant_id}")

        delivery_id = str(uuid.uuid4())

        # Store only the tenant_id, not a direct reference to context
        self._delivery_tenant_ids[delivery_id] = tenant_id

        metadata = {
            "delivery_id": delivery_id,
            "tenant_id": tenant_id,
            "recipient": recipient,
            "subject": subject,
            "status": "queued"
        }
        self._registry.store_pending(delivery_id, metadata)

        # Schedule async delivery
        asyncio.ensure_future(self._process_delivery(delivery_id, recipient, subject, body))
        return delivery_id

    async def _process_delivery(self, delivery_id: str, recipient: str, subject: str, body: str):
        # Simulate network delay for SMTP
        await asyncio.sleep(0.1)

        # Look up current tenant context fresh from registry
        tenant_id = self._delivery_tenant_ids.get(delivery_id)
        if tenant_id is None:
            return

        ctx = self._registry.get(tenant_id)

        if ctx is not None and not ctx._invalidated:
            # Increment sent count on the CURRENT context
            ctx.sent_count += 1

            # Fire tenant-specific callbacks with delivery result
            event = {
                "delivery_id": delivery_id,
                "status": "delivered",
                "recipient": recipient
            }
            ctx.fire_callbacks(event)

            # Update pending metadata
            pending = self._registry.get_pending(delivery_id)
            if pending:
                pending["status"] = "delivered"
        else:
            # Tenant was offboarded, mark delivery as cancelled
            pending = self._registry.get_pending(delivery_id)
            if pending:
                pending["status"] = "cancelled_tenant_removed"

        # Cleanup
        self._delivery_tenant_ids.pop(delivery_id, None)

    async def get_delivery_status(self, delivery_id: str) -> Optional[dict]:
        return self._registry.get_pending(delivery_id)


class MultiTenantEmailService:
    def __init__(self):
        self._registry = TenantRegistry()
        self._engine = EmailDeliveryEngine(self._registry)

    def onboard_tenant(self, tenant_id: str, api_key: str) -> TenantContext:
        return self._registry.register(tenant_id, api_key)

    def offboard_tenant(self, tenant_id: str):
        """Remove tenant and invalidate all associated contexts"""
        self._registry.unregister(tenant_id)

    async def send(self, tenant_id: str, recipient: str, subject: str, body: str) -> str:
        return await self._engine.send_email(tenant_id, recipient, subject, body)

    async def check_status(self, delivery_id: str) -> Optional[dict]:
        return await self._engine.get_delivery_status(delivery_id)


async def safe_scenario():
    """Demonstrates that cross-tenant data leak is prevented."""
    service = MultiTenantEmailService()

    # Tenant A onboards and registers a callback
    tenant_a = service.onboard_tenant("tenant_a", "secret_key_a")
    leaked_data = []

    def tenant_a_callback(event):
        leaked_data.append({"api_key": tenant_a.api_key, "event": event})

    tenant_a.register_callback(tenant_a_callback)

    # Tenant A sends an email
    delivery_id = await service.send("tenant_a", "user@example.com", "Hello", "Body")

    # Tenant A is offboarded - context is invalidated
    service.offboard_tenant("tenant_a")

    # Tenant B onboards with the same tenant_id
    tenant_b = service.onboard_tenant("tenant_a", "secret_key_b")

    # The in-flight delivery completes - old context is invalidated
    # so callbacks won't fire and sent_count goes to new context
    await asyncio.sleep(0.2)

    # No data leaked - old callbacks were cleared on invalidation
    print(f"Leaked data (should be empty): {leaked_data}")
    print(f"Tenant B sent_count: {tenant_b.sent_count}")


if __name__ == "__main__":
    asyncio.run(safe_scenario())
